"""GNU wide enum and switch semantics, checked against the i386 compiler."""
valid = [
    ("enum-wide-range", b"enum E{A=-1,B=0xffffffffU};int main(){return 0;}", 0),
    ("ll-switch-pending", b"int main(){long long x=1;switch(x){case 1:return 7;}return 0;}", 7),
    ("ll-enum-pending", b"enum E{A=1ULL<<32};int main(){return A;}", 0),
    ("switch64-high", b"int main(){unsigned long long x=1ULL<<32;switch(x){case 0:return 1;case 1ULL<<32:return 7;}return 0;}", 7),
    ("switch64-low-collision", b"int main(){unsigned long long x=0x200000007ULL;switch(x){case 7:return 1;case 0x100000007ULL:return 2;case 0x200000007ULL:return 7;}return 0;}", 7),
    ("switch64-signed-range", b"int main(){long long x=-4294967297LL;switch(x){case -4294967298LL ... -4294967296LL:return 7;}return 0;}", 7),
    ("switch64-unsigned-range", b"int main(){unsigned long long x=0xffffffffffffffffULL;switch(x){case 0xfffffffffffffff0ULL ... 0xffffffffffffffffULL:return 7;}return 0;}", 7),
    ("switch64-zero-crossing", b"int main(){long long x=-1;switch(x){case -4294967297LL ... 4294967297LL:return 7;}return 0;}", 7),
    ("switch64-default", b"int main(){unsigned long long x=1ULL<<40;switch(x){case 1:return 3;default:return 7;}}", 7),
    ("switch64-reversed", b"int main(){long long x=1LL<<32;switch(x){case 2LL<<32 ... 1LL<<32:return 3;default:return 7;}}", 7),
    ("switch64-fallthrough", b"int main(){long long x=1LL<<32;int n=0;switch(x){case 1LL<<32:n+=3;case 2LL<<32:n+=4;break;default:n=9;}return n;}", 7),
    ("switch64-nested", b"int main(){long long x=1LL<<32;switch(x){case 1LL<<32:switch(-x){case -(1LL<<32):return 7;}break;}return 0;}", 7),
    ("switch64-once", b"int n;long long f(){n++;return 1LL<<32;}int main(){switch(f()){case 1LL<<32:return n+6;}return 0;}", 7),
    ("switch64-cast32", b"int main(){int x=-1;switch(x){case 0xffffffffULL:return 7;}return 0;}", 7),
    ("switch64-volatile", b"int main(){volatile unsigned long long x=1ULL<<32;switch(x){case 0:return 1;case 1ULL<<32:return 7;}return 0;}", 7),
    ("enum64-unsigned", b"enum E{A=1ULL<<32,B};int main(){return (B>>32)+sizeof(enum E);}", 9),
    ("enum64-signed", b"enum E{A=-(1LL<<32),B};int main(){return sizeof(enum E)+(A<0)+(B-A);}", 10),
    ("enum64-mixed", b"enum E{A=-1,B=0xffffffffU};int main(){return sizeof(enum E)+(A==-1)+(B>0);}", 10),
    ("enum64-final-type", b"enum E{A=0x80000000U,B=1ULL<<32};int main(){return sizeof(A)+sizeof(enum E)+(A>>31);}", 17),
    ("enum64-maximum", b"enum E{A=0xffffffffffffffffULL};int main(){return A>>32;}", -1),
    ("enum64-compatible", b"enum E{A=1ULL<<32};_Static_assert(__builtin_types_compatible_p(enum E,unsigned long long),\"enum\");int main(){return 7;}", 7),
    ("enum64-negative-compatible", b"enum E{A=-(1LL<<32)};_Static_assert(__builtin_types_compatible_p(enum E,long long),\"enum\");int main(){return 7;}", 7),
    ("enum64-small-type", b"enum E{A=1,B=1ULL<<32};_Static_assert(__builtin_types_compatible_p(typeof(A),int),\"small\");int main(){return 7;}", 7),
    ("enum64-small-long-long", b"enum E{A=3LL};int main(){return sizeof(A)+sizeof(enum E);}", 8),
    ("enum64-global", b"enum E{A=1ULL<<32};enum E x=A;int main(){return sizeof(x)+(x>>32);}", 9),
    ("enum64-array", b"enum E{A=1ULL<<32,B};int main(){enum E a[2]={A,B};return sizeof(a)+(a[1]-a[0]);}", 17),
    ("enum64-field", b"enum E{A=1ULL<<32};struct S{char c;enum E e;};int main(){struct S s={1,A};return sizeof(s)+__builtin_offsetof(struct S,e)+(s.e>>32);}", 17),
    ("enum64-argument", b"enum E{A=1ULL<<32};enum E f(enum E x){return x;}int main(){return f(A)>>32;}", 1),
    ("enum64-varargs", b"enum E{A=1ULL<<32};unsigned long long f(int n,...){__builtin_va_list a;__builtin_va_start(a,n);unsigned long long x=__builtin_va_arg(a,unsigned long long);__builtin_va_end(a);return x;}int main(){return f(1,A)>>32;}", 1),
    ("enum64-switch", b"enum E{A=1ULL<<32};int main(){enum E x=A;switch(x){case A:return 7;}return 0;}", 7),
    ("enum64-references", b"enum E{A=1ULL<<32,B=A+1,C=B+1};int main(){return C-A;}", 2),
]
volatile_reads = {"switch64-volatile": (1,96,64)}
invalid = [
    ("switch64-duplicate", b"int main(){long long x=0;switch(x){case 1LL<<32:return 1;case 1ULL<<32:return 2;}return 0;}"),
    ("switch64-overlap", b"int main(){long long x=0;switch(x){case 1LL<<32 ... (1LL<<32)+3:return 1;case (1LL<<32)+2:return 2;}return 0;}"),
    ("switch64-truncated-duplicate", b"int main(){int x=0;switch(x){case 0:return 1;case 1ULL<<32:return 2;}return 0;}"),
    ("enum64-signed-increment-overflow", b"enum E{A=9223372036854775807LL,B};int main(){return 0;}"),
    ("enum64-unsigned-increment-overflow", b"enum E{A=0xffffffffffffffffULL,B};int main(){return 0;}"),
]
